style.css:
@-moz-document domain("youtube.com") {
/* 1. FONDO ROSA AURA CON CHIIKAWA INTEGRADO */
    ytd-app, 
    ytd-page-manager, 
    #page-manager, 
    #content, 
    #columns,
    #background,
    #masthead-container,
    tp-yt-app-drawer {
        background-color: #FFF0F5 !important;
        background-image: url('https://ibb.co') !important;
        background-attachment: fixed !important;
        background-size: cover !important;
        background-position: center !important;
        background-repeat: no-repeat !important;
    }

    /* 2. TEXTOS DE LOS VIDEOS Y COMENTARIOS: Blanco Puro */
    #video-title, 
    #channel-name, 
    #content-text, 
    span, 
    a, 
    h1, 
    h2, 
    h3, 
    #title,
    #description-text,
    yt-formatted-string,
    .ytd-comment-renderer {
        color: #FFFFFF !important;
        text-shadow: 1px 1px 3px rgba(0, 0, 0, 0.5) !important;
    }

    /* 3. ICONOS GENERALES DE LA PÁGINA: Blanco Puro */
    svg, path, yt-icon {
        fill: #FFFFFF !important;
        color: #FFFFFF !important;
    }

    /* 4. BUSCADOR SUPERIOR: Amarillo Pollito */
    #search-form, 
    #container.ytd-searchbox, 
    input#search,
    .ytd-searchbox {
        background-color: #FFF59D !important;
        border: 2px solid #FF8AAB !important;
        border-radius: 40px 0 0 40px !important;
    }
    #search-icon-legacy, #search-icon-legacy yt-icon {
        background-color: #FFF59D !important;
        border: 2px solid #FF8AAB !important;
        border-radius: 0 40px 40px 0 !important;
    }
    #search-icon-legacy svg path {
        fill: #4A4A4A !important;
    }
    input#search {
        color: #4A4A4A !important;
    }

    /* 5. ¡DISEÑO EXCLUSIVO AMARILLO CON LÍNEAS ROSAS PARA BOTONES! */
    /* Aquí agrupamos Suscribirse, Likes, Compartir, Remix, Descargar y Clips */
    ytd-subscribe-button-renderer version-cards,
    #subscribe-button button,
    .ytd-subscribe-button-renderer,
    ytd-button-renderer.ytd-menu-renderer,
    #segmented-like-button button,
    #segmented-dislike-button button,
    yt-button-shape button,
    .yt-spec-button-shape-next--mono,
    .yt-spec-button-shape-next--size-m {
        background-color: #FFF59D !important; /* Fondo Amarillo Pollito */
        border: 2px dashed #FFB7CE !important; /* Líneas discontinuas rosadas alrededor */
        border-radius: 20px !important; /* Bordes redonditos suaves */
        padding: 4px 12px !important;
        box-shadow: 2px 2px 5px rgba(0,0,0,0.05) !important;
    }

    /* Forzamos que las letras y los iconos dentro de estos botones sean oscuros para que se lean perfectos en el amarillo */
    #subscribe-button yt-formatted-string,
    yt-button-shape button span,
    yt-button-shape button yt-icon,
    .yt-spec-button-shape-next__button-text-content,
    .yt-spec-button-shape-next__icon yt-icon,
    #segmented-like-button yt-icon,
    #segmented-dislike-button yt-icon {
        color: #4A4A4A !important;
        fill: #4A4A4A !important;
    }

    /* 6. MARCOS DE LÍNEAS ROSADAS ALREDEDOR DE LOS VIDEOS (INICIO) */
    ytd-rich-grid-media, 
    ytd-compact-video-renderer, 
    #dismissible.ytd-thumbnail {
        border: 3px dashed #FFB7CE !important;
        border-radius: 12px !important;
        padding: 8px !important;
        background-color: rgba(255, 240, 245, 0.4) !important;
        box-shadow: 2px 2px 8px rgba(0,0,0,0.05) !important;
    }

    /* 7. BARRITA DE TIEMPO ROSADA CON STICKER DE MY MELODY */
    .ytp-play-progress {
        background: #FF8AAB !important;
    }
    .ytp-load-progress, .ytp-progress-list {
        background: rgba(255, 255, 255, 0.4) !important;
    }
    .ytp-scrubber-button {
        background: url('https://icons8.com') no-repeat center !important;
        background-size: contain !important;
        width: 28px !important;
        height: 28px !important;
        border-radius: 0% !important;
        box-shadow: none !important;
    }
}
